import React, { useState, useEffect } from 'react';
import PageWrapper from '../../../layout/PageWrapper/PageWrapper';
import Page from '../../../layout/Page/Page';
import useMinimizeAside from '../../../hooks/useMinimizeAside';
import { dashboardMenu2 } from '../../../menu_agent';
import Card, { CardBody, CardHeader } from '../../../components/bootstrap/Card';
import Button from '../../../components/bootstrap/Button';
import axios from 'axios';
import { format } from 'date-fns';

const Chat = () => {
	useMinimizeAside();
	const id = localStorage.getItem('sess_id');
	const [editorData, setEditorData] = useState({ description: '' });



	const [activeMember, setActiveMember] = useState([]);
	const [activeMemberGroup, setActiveMemberGroup] = useState(false);
	const [activeMemberId, setActiveMemberId] = useState([]);
	const [activeMemberName, setActiveMemberName] = useState([]);
	const [activeGroupChat, setActiveGroupChat] = useState([]);
	const [activeChatList, setActiveChatList] = useState([]);
	// Assuming you have a state for the file, like this:
	const [selectedFile, setSelectedFile] = useState(null);

	let imgUrl = 'https://task.mycrmdesk.com/backend/public/uploads/'



	useEffect(() => {

		async function getActiveMemberList() {
			try {
				const activeMemApi = await axios.get(`https://task.mycrmdesk.com/backend/api/admin/all-agent-list-data`)
				setActiveMember(activeMemApi.data);
			} catch (error) {
				console.log("Something is Wrong -Assignee");
			}
		}

		async function getActiveGroupChatList() {
			try {
				const activeChatApi = await axios.get(`https://task.mycrmdesk.com/backend/api/admin/all-agent-chat-group/${id}`)
				setActiveGroupChat(activeChatApi.data);
			} catch (error) {
				console.log("Something is Wrong -Assignee");
			}
		}

		getActiveMemberList();
		getActiveGroupChatList();
	}, [id]);



	useEffect(() => {
		bootomReload();
	}, []);

	function bootomReload() {
		const contentContainer = document.querySelector(".msger-chat");
		// Scroll to the bottom of the container on page load or refresh
		contentContainer.scrollTop = contentContainer.scrollHeight;
	}

	async function onMemeberChat(e, memId, memName) {
		window.scrollTo({ top: 0, behavior: 'smooth' });
		setActiveMemberGroup(false);
		setActiveMemberId(memId);
		setActiveMemberName(memName);
		getActiveChatList(memId);
		// console.log("member id",memId);
	}

	async function onMemeberChatGrp(e, memId, memName) {
		window.scrollTo({ top: 0, behavior: 'smooth' });
		setActiveMemberGroup(true);
		setActiveMemberId(memId);
		setActiveMemberName(memName);
		getActiveChatListGrp(memId);

	}

	async function getActiveChatList(memId) {
		try {
			// if(activeMemberId == id){

			// }
			const activeChatListApi = await axios.get(`https://task.mycrmdesk.com/backend/api/admin/chat-list-history/${id}/${memId}`)
			setActiveChatList(activeChatListApi.data.data);
			console.log(activeChatListApi.data)
		} catch (error) {
			console.log("Something is Wrong -chat List History");
		}
	}

	async function getActiveChatListGrp(memId) {
		try {
			const activeChatListApi = await axios.get(`https://task.mycrmdesk.com/backend/api/admin/chat-list-history-group/${id}/${memId}`)
			setActiveChatList(activeChatListApi.data.data);
		} catch (error) {
			console.log("Something is Wrong -chat List History");
		}
	}

	const onFormSubmit = async (e) => {
		e.preventDefault();
		 if (activeMemberId == '' || activeMemberId == null) {
			alert('Select Member First to Chat !!!');
			window.scrollTo({ top: 0, behavior: 'smooth' });
		}
		else if ((editorData.description == '' || editorData.description == null) && !selectedFile) {
			alert('Fill Message First !!!');
			window.scrollTo({ top: 0, behavior: 'smooth' });
		}  else {

		}
		try {
			// If both text and image are present, send them together
			if (editorData.description && selectedFile) {
				await sendTextAndImage();
			} else {
				// If only text or only image is present, send accordingly
				if (editorData.description) {
					await sendText();
				} else if (selectedFile) {
					await sendImage();
				}
				
			}

			// Clear form fields
			setEditorData({ description: '' });
			setSelectedFile(null);
			e.target.reset(); // Add this line to reset the form

		} catch (error) {
			console.error('Error during form submission:', error);
			alert('Something went wrong');
		}
	};

	const sendTextAndImage = async () => {
		const formData = new FormData();
		formData.append('message', editorData.description);
		formData.append('file', selectedFile);
		// Log the Content-Type of the selected file
		// alert(selectedFile.type);
		


		const res = await axios.post(`https://task.mycrmdesk.com/backend/api/agent/start-chat/${id}/${activeMemberId}?is_group=${activeMemberGroup ? 1 : 2}`, formData, {
			headers: {
				'Content-Type': 'multipart/form-data',
			},
		});

		// Display a notification to the user
		alert('Message sent successfully!');

		// Clear form fields
		setEditorData({ description: '' });
		console.log("id", id);
		console.log("member id", activeMemberId);
		setSelectedFile(null);

		console.log(res.data);
	};

	const sendText = async () => {
		const body = {
			message: editorData.description,
		};

		const res = await axios.post(`https://task.mycrmdesk.com/backend/api/agent/start-chat/${id}/${activeMemberId}?is_group=${activeMemberGroup ? 1 : 2}`, body);

		console.log(res.data);
	};

	const sendImage = async () => {
		const formData = new FormData();
		formData.append('file', selectedFile);
		console.log(selectedFile);


		const res = await axios.post(`https://task.mycrmdesk.com/backend/api/agent/start-chat/${id}/${activeMemberId}?is_group=${activeMemberGroup ? 1 : 2}`, formData, {
			headers: {
				'Content-Type': 'multipart/form-data',
			},
		});

		console.log(res.data);
	};



	useEffect(() => {
		const interval = setInterval(() => {
			if (activeMemberGroup == true) {
				getActiveChatListGrp(activeMemberId);
			} else {
				getActiveChatList(activeMemberId);


			}

		}, 5000);
		return () => clearInterval(interval);
	}, [activeMemberId]);




	return (
		<PageWrapper title={dashboardMenu2.chat.text}>

			<Page style={{ marginTop: 0, paddingTop: 0 }}>

				<div id='bootstrap' className='row scroll-margin h-100'>
					<div className='col-md-3 col-xs-12'>
						<Card stretch>
							<CardHeader className=''>
								<h4>Chat Group</h4>
							</CardHeader>
							<CardBody className='' style={{height: "100px", overflow: "auto"}}>

								{
									activeGroupChat && activeGroupChat.length > 0 ?
										activeGroupChat.map((item, index) => (
											<p key={index + 1} onClick={e => onMemeberChatGrp(e, item.id, item.name)} className='' style={{cursor: "pointer"}} >{item.name}</p>
										)) :
										<h4> No Group Found !!</h4>
								}

							</CardBody>
						</Card>

						<Card stretch>
							<CardHeader className=''>
								<h4>Members</h4>
							</CardHeader>
							<CardBody className=''  style={{height: "400px", overflow: "auto"}}>

								{
									activeMember && activeMember.length > 0 ?
										activeMember.map((item, index) => (
											<p key={index + 1} onClick={e => onMemeberChat(e, item.id, item.name)} className='' style={{cursor: "pointer"}}>{item.name}</p>
										)) :
										<h4> No Member Found !!</h4>
								}

							</CardBody>
						</Card>
					</div>

					<div className='col-md-9 col-xs-12'>
						<Card stretch>
							<CardHeader className=''>
								<h4>Chat with {activeMemberName}</h4>
							</CardHeader>
							<CardBody className=''>

								<section className="msger">


									<main className="msger-chat" style={{ maxHeight: '300px' }}>

										{
											activeChatList && activeChatList.length > 0 ? (
												activeChatList.map((item, index) => (
													<div className="msg left-msg" key={index + 1}>
														<div className="msg-bubble">
															<div className="msg-info">
																<div className="msg-info-name">{item.mem_name}</div>
																<div className="msg-info-time">
																	{format(new Date(item.created_at), 'yyyy-MM-dd H:i:s')}
																</div>
															</div>
															<div className="msg-text">
																<div dangerouslySetInnerHTML={{ __html: item.message }} />

																{item.image && (
																	<div>
																	
																	

																		<a href={`${imgUrl}${item.image}`} download>

																			{(item.image.endsWith('.jpg') || item.image.endsWith('.jpeg') || item.image.endsWith('.png') || item.image.endsWith('.gif')) ? (
																				<img
																					src={`${imgUrl}${item.image}`}
																					alt="Image description"
																					style={{ width: '300px', objectFit: 'cover', cursor: 'pointer' }}
																				/>

																			) : (
																				<div className='d-flex justify-content-between'>
																					<p><svg xmlns="http://www.w3.org/2000/svg" x="0px" y="0px" width="25" height="25" viewBox="0 0 30 30">
																						<path d="M24.707,8.793l-6.5-6.5C18.019,2.105,17.765,2,17.5,2H7C5.895,2,5,2.895,5,4v22c0,1.105,0.895,2,2,2h16c1.105,0,2-0.895,2-2 V9.5C25,9.235,24.895,8.981,24.707,8.793z M18,10c-0.552,0-1-0.448-1-1V3.904L23.096,10H18z"></path>
																					</svg></p>
																					<p>
																					<svg xmlns="http://www.w3.org/2000/svg" data-name="Layer 1" viewBox="0 0 24 24" id="download" width="25" height="25"><path d="M14.29,17.29,13,18.59V13a1,1,0,0,0-2,0v5.59l-1.29-1.3a1,1,0,0,0-1.42,1.42l3,3a1,1,0,0,0,.33.21.94.94,0,0,0,.76,0,1,1,0,0,0,.33-.21l3-3a1,1,0,0,0-1.42-1.42ZM18.42,6.22A7,7,0,0,0,5.06,8.11,4,4,0,0,0,6,16a1,1,0,0,0,0-2,2,2,0,0,1,0-4A1,1,0,0,0,7,9a5,5,0,0,1,9.73-1.61,1,1,0,0,0,.78.67,3,3,0,0,1,.24,5.84,1,1,0,1,0,.5,1.94,5,5,0,0,0,.17-9.62Z"></path></svg>

																					</p>
																				</div>
																			)}
																		</a>


																		{/* <button
																			onClick={() =>
																				handleDownload(`${imgUrl}${item.image}`, `${item.mem_name}`)
																			}
																		>
																			Download Image
																		</button> */}
																	</div>
																)}
															</div>
														</div>
													</div>
												))
											) : (
												<h4>No Chat Found !!</h4>
											)
										}



										{/*
    <div className="msg right-msg">
      <div className="msg-bubble">
        <div className="msg-info">
          <div className="msg-info-name">Sajad</div>
          <div className="msg-info-time">12:46</div>
        </div>
        <div className="msg-text">
          You can change your name in JS section!
        </div>
      </div>
    </div>
	*/}




									</main>

								</section>


							</CardBody>
						</Card>

						<Card stretch>

							<CardBody className=''>


								<form onSubmit={onFormSubmit}>
									<textarea
										className='form-control mb-3'
										name="description"
										rows={3}
										id='name'
										value={editorData.description}
										onChange={(e) => setEditorData({ ...editorData, description: e.target.value })}
									></textarea>

									<input
										type="file"
										onChange={(e) => setSelectedFile(e.target.files[0])}
										className='d-block mb-3'
									/>

									{/* <button type="submit">Send</button> */}
									<Button
										color='info'
										className=' py-6'
										type='submit'
									>
										Send
									</Button>

								</form>
							</CardBody>
						</Card>


					</div>

				</div>
			</Page>
		</PageWrapper>
	);
};

export default Chat;


